#!/bin/bash
# converge.sh: make ~/.claude match this repo. Idempotent. Safe to run at any time.
#
# WHY THIS EXISTS. The deploy has three surfaces with three different update semantics:
#
#   symlinked trees (hooks/ commands/ skills/ git-hooks/)  → follow `git pull` instantly
#   ~/.claude/settings.json                                → GENERATED by deploy.sh
#   launchd plists                                         → INSTALLED by install-agents.sh
#
# So `git pull` alone half-deploys, and the half it misses fails SILENTLY: because the hooks
# dir is a symlink into this repo, a pull that deletes a hook removes it from the live tree
# instantly, while launchd keeps firing the plist it already holds at a script that is now
# gone. That is a job which is neither running nor visibly dead. (Worked example: the
# nm-guard retirement, 734fafc.)
#
# This script is the whole deploy, and it has two callers that make remembering it
# unnecessary, the point is that a human never types it:
#
#   1. .git/hooks/{post-merge,post-rewrite,post-checkout} → git-hooks/  (installed by deploy.sh)
#      so `git pull` IS the deploy, structurally.
#   2. the `converge` per_host launchd agent (see launchd/install-agents.sh)
#      so drift heals on a timer even when the hooks are bypassed, a GUI client,
#      `git fetch && git reset --hard`, or a clone whose core.hooksPath was never set.
#
# Git hooks are best-effort; the timer is the guarantee. Neither is load-bearing alone.
#
# MODES
#   (default)     full converge: deploy.sh + install-agents.sh. Interactive/after-a-pull.
#   --scheduled   unattended. Refuses to RESHAPE ~/.claude (deploy.sh moves a real dir aside
#                 to a backup, correct when a human ran it, a surprise at 06:30). Verifies
#                 the deploy is already symlinked, converges launchd only, and alerts +
#                 exits nonzero otherwise. Leaves the marker UNARMED on any failure, so a
#                 stale converge-last-success means "the healer died".
set -u

REPO="$(cd "$(dirname "$0")" && pwd -P)"
SCHEDULED=""
[ "${1:-}" = "--scheduled" ] && SCHEDULED=1

# Recursion guard: install-agents.sh renders the converge plist, and a future caller could
# re-enter. Cheap insurance, this script must never invoke itself.
if [ -n "${ORGANISM_CONVERGE_RUNNING:-}" ]; then
  echo "converge: already running (re-entered): skipping"
  exit 0
fi
export ORGANISM_CONVERGE_RUNNING=1

# Tell install-agents.sh which label is US, so it re-renders the converge plist but does NOT
# `launchctl unload` it, unloading a RUNNING job SIGTERMs it, and converge would kill itself
# mid-run, before the orphan sweep and the success marker. (Its plist is still refreshed on
# disk; a changed converge schedule lands on the next boot or the next interactive run.)
#
# Only under --scheduled, i.e. only when launchd is what invoked us. A human running
# `bash converge.sh` from a shell is NOT the launchd job: unloading that plist cannot kill this
# process, and it MUST be allowed to load, otherwise the very first converge would render its
# own agent and never start it, and the timer that makes this whole thing work would not exist.
[ -n "$SCHEDULED" ] && export ORGANISM_SELF_LABEL="${ORGANISM_LAUNCHD_NS:-com.organism}.converge"

HOOKS_LINK="$HOME/.claude/hooks"
fail() {  # message: alert only when unattended (a human running this can read stderr).
  # ORGANISM_DRY suppresses the alert so the test suite can exercise every failure path
  # without firing a real banner/Telegram push at whoever is running it.
  echo "✗ converge: $1" >&2
  if [ -n "$SCHEDULED" ] && [ -z "${ORGANISM_DRY:-}" ] && [ -f "$REPO/claude/hooks/alert.py" ]; then
    python3 "$REPO/claude/hooks/alert.py" --title "converge failed" --text "$1" >/dev/null 2>&1 || true
  fi
  exit 1
}

. "$REPO/claude/hooks/lib/color.sh"
h1 "converge: $REPO -> ~/.claude"

if [ -n "$SCHEDULED" ]; then
  # Unattended: assert, never reshape. deploy.sh backs up a real ~/.claude/hooks before
  # relinking; that is the right call for a human and the wrong one for a timer.
  [ -L "$HOOKS_LINK" ] || fail "~/.claude/hooks is not a symlink: run deploy.sh by hand (refusing to reshape ~/.claude unattended)"
  [ "$(readlink "$HOOKS_LINK")" = "$REPO/claude/hooks" ] \
    || fail "~/.claude/hooks points at $(readlink "$HOOKS_LINK"), not $REPO/claude/hooks: refusing to relink unattended"
  echo "  ✓ deploy already linked (scheduled mode: launchd only)"
else
  bash "$REPO/deploy.sh" || fail "deploy.sh failed: NOT converging launchd against a half-deployed tree"
fi

bash "$REPO/launchd/install-agents.sh" || fail "install-agents.sh failed"

# Success marker LAST, and only on a genuinely clean run (freshness-marker contract).
python3 - "$REPO" <<'PY' || fail "could not write the converge-last-success marker"
import sys, os
sys.path.insert(0, os.path.join(sys.argv[1], "claude", "hooks"))
from lib.jobstatus import mark_success
raise SystemExit(0 if mark_success("converge") else 1)
PY

h1 "converge: done"
